    "key": "13_closure",
    "title": "13 Closure",
    "filename": "13_closure.php",
    "php": "<?php\n$x = 10;\n\n// 测试普通闭包和外部捕获\n$cb = function($y) use ($x) {\n    return $x + $y;\n};\necho $cb(5);\necho \"\\n\";\n\n// 测试箭头函数和隐式捕获\n$fn = fn($z) => $z * $x;\necho $fn(3);\necho \"\\n\";\n",
    "v": "import php2v.rt\n\nfn call_method(obj rt.PhpVal, method_name string, args []rt.PhpVal) rt.PhpVal {\n\treturn rt.new_null()\n}\n\nfn get_property(obj rt.PhpVal, prop_name string) rt.PhpVal {\n\treturn rt.new_null()\n}\n\nfn set_property(obj rt.PhpVal, prop_name string, val rt.PhpVal) {}\n\nstruct Closure_1 {\n\trt.PhpObjectBase\npub mut:\n\tprop_x rt.PhpVal\n}\n\nfn (mut this Closure_1) invoke(args []rt.PhpVal) rt.PhpVal {\n\tmut var_y := if args.len > 0 { args[0].dup() } else { rt.new_null() }\n\tmut var_x := this.prop_x.dup()\n\treturn rt.add(var_x, var_y)\n}\n\nstruct Closure_2 {\n\trt.PhpObjectBase\npub mut:\n\tprop_x rt.PhpVal\n}\n\nfn (mut this Closure_2) invoke(args []rt.PhpVal) rt.PhpVal {\n\tmut var_z := if args.len > 0 { args[0].dup() } else { rt.new_null() }\n\tmut var_x := this.prop_x.dup()\n\treturn rt.mul(var_z, var_x)\n}\n\nfn call_closure(cb rt.PhpVal, args []rt.PhpVal) rt.PhpVal {\n\tif !cb.is_object() { return rt.new_null() }\n\tmut obj_info := cb.get_object()\n\tmatch obj_info.class_name {\n\t\t'Closure_1' {\n\t\t\tif mut obj_info.obj is Closure_1 {\n\t\t\t\treturn obj_info.obj.invoke(args)\n\t\t\t}\n\t\t}\n\t\t'Closure_2' {\n\t\t\tif mut obj_info.obj is Closure_2 {\n\t\t\t\treturn obj_info.obj.invoke(args)\n\t\t\t}\n\t\t}\n\t\telse {}\n\t}\n\treturn rt.new_null()\n}\n\n\nfn main() {\n\tdefer {\n\t\trt.shutdown()\n\t}\n\n\tmut var_z := rt.new_null()\n\tmut var_x := rt.new_int(10)\n\tmut var_cb := rt.new_object('Closure_1', ['Closure'], &Closure_1{ prop_x: var_x.dup() })\n\trt.echo_val(call_closure(var_cb, [rt.new_int(5)]))\n\trt.echo_val(rt.new_string('\\n'))\n\tmut var_fn := rt.new_object('Closure_2', ['Closure'], &Closure_2{ prop_x: var_x.dup() })\n\trt.echo_val(call_closure(var_fn, [rt.new_int(3)]))\n\trt.echo_val(rt.new_string('\\n'))\n}\n",
