    "php": "<?php\n$a = 5;\n\n// 测试后置自增\n$b = $a++;\necho \"b is \" . $b . \", a is \" . $a . \"\\n\";\n\n// 测试后置自减\n$c = $a--;\necho \"c is \" . $c . \", a is \" . $a . \"\\n\";\n\n// 测试前置自增\n$d = ++$a;\necho \"d is \" . $d . \", a is \" . $a . \"\\n\";\n\n// 测试前置自减\n$e = --$a;\necho \"e is \" . $e . \", a is \" . $a . \"\\n\";\n",
